sample.code:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string first = "Ali";
    string last = "Khan";
    string full = first + " " + last;
    cout << full << endl;
    cout << "Length: " << full.length() << endl;
    cout << "First letter: " << full[0] << endl;
    cout << "Second letter: " << full.at(1) << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string first, full;
    int age;
    cin >> first;
    cin >> age;
    cin.ignore();
    getline(cin, full);
    cout << "Hi " << first << " (" << full << "), age " << age << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string w;
    cin >> w;
    int count = 0;
    for (size_t i = 0; i < w.length(); i++) {
        cout << w[i] << " = " << (int)w[i] << endl;
        if (w[i] == 'a') {
            count++;
        }
    }
    cout << "Letter a appears " << count << " times" << endl;
    return 0;
}

